"""CPU acceptance, evidence limits, and immutable historical verification."""
from .common import *
from .optimizer import predict_scenarios
import statistics,itertools

def main():
 defi=read(OUT/'utility_definition.json');man=read(OUT/'utility_reference_manifest.json');hist=read(OUT/'historical_analysis.json');diagn=read(OUT/'diagnosis_and_validation.json');perf=read(OUT/'search_performance.json');cells=table(OUT/'optimizer_search_grid.csv');weights=table(OUT/'weight_sensitivity.csv');frozen=read(OUT/'frozen_module20b_candidates.json');cpu=read(ROOT/'results/module19_strategy_benchmark/cpu_results.json')['results'];refs=man['latency_reference_ms'];mainw=defi['weights'];A=[];Asens=[];diagnosis=[]
 for rec in cpu:
  case=rec['case'];cid=case['case_id']
  if cid not in ['text_high','image_high','lid_mid','lid_high']:continue
  d=read(case['catalog']['path']);old=rec['strategies']['PROPOSED']['fit']['winner'];x=old['deployment'];rr={t:{} for t in case['rates']}
  for key,v in old['routing'].items():
   t,m=key.split('::');rr[t][m]=v
  target=case['target_task'];G=[m for m in x if d['models'][m]['role']=='generalist' and target in d['models'][m]['supported_tasks']];S=[m for m in x if d['models'][m]['role']=='specialist' and target in d['models'][m]['supported_tasks']];candidates=[]
  for frac in [0.,.01,.05,.2,.5,1.,sum(rr[target].get(m,0) for m in G)/case['rates'][target]]:
   if (frac>0 and not G) or (frac<1 and not S):continue
   r={t:dict(v) for t,v in rr.items()};r[target]={}
   for role,share in [(G,frac),(S,1-frac)]:
    if share>0:
     m=min(role,key=lambda m:d['models'][m]['service_time_ms'][target]);r[target][m]=case['rates'][target]*share
   p=predict_scenarios(d,x,r,case['rates'],case['budget_mib'],refs,mainw);candidates.append({'fraction':frac,'routing':r,'prediction':p})
  valid=[c for c in candidates if c['prediction']['eligible']];win=max(valid,key=lambda c:c['prediction']['U']);A.append({'case_id':cid,'old_target_G_fraction':sum(rr[target].get(m,0) for m in G)/case['rates'][target],'new_selected_G_fraction':win['fraction'],'new_selected_U':win['prediction']['U'],'new_selected_operational_08':win['prediction']['operational_rho_08'],'runtime_certified':False,'still_selects_mixed':0<win['fraction']<1,'candidates':candidates})
  for w in defi['sensitivity_grid']:
   def U(c):return -sum(w[k]*c['prediction'][k+'_norm'] for k in ['T','L','P','M'])
   selected=max(valid,key=U);Asens.append({'case_id':cid,'weight_id':w['id'],'new_selected_G_fraction':selected['fraction'],'still_selects_mixed':0<selected['fraction']<1,'same_fraction_as_main':selected['fraction']==win['fraction']})
  a=[r for r in hist if r['module']==19 and r['config_id']==cid+'_proposed'];ctrl=cid+'_fixed_s_only' if cid=='image_high' else cid+'_s_oriented';b=[r for r in hist if r['module']==19 and r['config_id']==ctrl]
  z=next(z for z in diagn['routing_diagnoses'] if z['case_id']==cid)
  row={'case':cid,'mean_delta_U_GS_minus_S':z['mean_delta_U'],'J_U_reversals':z['J_U_reversal_count'],'new_correct_pairs':z['new_correct_count']}
  for arm,runs in [('GS',a),('S',b)]:
   for key in ['CPU_predicted_J_ms','actual_system_mean_ms','actual_pooled_request_P95_ms','actual_within_window_QPS','U','L_norm','P_norm','T_norm','M_norm']:
    vals=[r[key] for r in runs if r.get(key) is not None];row[arm+'_'+key]=statistics.mean(vals) if vals else None
   row[arm+'_CPU_rho']=runs[0]['CPU_predicted_rho'] if runs else None;row[arm+'_worker_states']=[r['worker_states'] for r in runs]
  diagnosis.append(row)
 save('negative_routing_acceptance.json',A);csvsave('negative_routing_weight_sensitivity.csv',Asens);csvsave('old_algorithm_diagnosis.csv',diagnosis)
 # All Module19 independently observed deployment contrasts; aliases are one physical configuration.
 f=read(ROOT/'results/module19_strategy_benchmark/frozen_benchmark_manifest.json');comparisons=[];seen=set()
 for c in f['comparisons']:
  if c['kind']!='DEPLOYMENT_STRATEGY' or not c.get('control_id'):continue
  ident=(c['case_id'],c['proposed_id'],c['control_id'])
  if ident in seen:continue
  seen.add(ident)
  for rep in [1,2,3]:
   a=next((r for r in hist if r['module']==19 and r['config_id']==c['proposed_id'] and r['repetition']==rep),None);b=next((r for r in hist if r['module']==19 and r['config_id']==c['control_id'] and r['repetition']==rep),None)
   if not a or not b:continue
   delta=a['U']-b['U'] if a['U'] is not None and b['U'] is not None else None;pred=a['predicted_U']-b['predicted_U'] if a['predicted_U'] is not None and b['predicted_U'] is not None else None
   comparisons.append({'case_id':c['case_id'],'control_label':c['control_label'],'proposed_id':c['proposed_id'],'control_id':c['control_id'],'configuration_equivalent':c['configuration_equivalent'],'repetition':rep,'actual_delta_U':delta,'predicted_delta_U':pred,'correct':delta*pred>0 if delta is not None and pred is not None and delta!=0 else None,'actual_memory_saving_mib':b['observed_safe_memory_mib']-a['observed_safe_memory_mib'],'positive_memory_does_not_imply_positive_U':True,'independent_validation':False,'full_original_V3_comparison':False})
 csvsave('all_observed_deployment_contrasts.csv',comparisons)
 hold=[r for r in hist if r['module']==16];valid_hold=[r for r in hold if r['U'] is not None and r['predicted_U'] is not None];mae=statistics.mean(abs(r['U']-r['predicted_U']) for r in valid_hold);falsefeas=[r['run_id'] for r in hold if not r['eligible'] and r['predicted_U'] is not None];cover=[r for r in valid_hold if r['scenario_U_low'] is not None];contained=sum(r['scenario_U_low']<=r['U']<=r['scenario_U_high'] for r in cover)
 groups=read(OUT/'three_phase_all_groups.json');natural=sum(g['natural_structural_triples'] for g in groups);positive=len(frozen['positive_three_phase_candidates']);reduction=[float(c['state_visit_reduction_fraction_vs_naive']) for c in cells];mixcells=sum(c['selected_G_fraction'] not in ['',None] and 1e-7<float(c['selected_G_fraction'])<1-1e-7 for c in cells)
 gate={'at_utc':now(),'module':'20A','CPU_only':True,'GPU_started':False,'independent_dimensions':{'UTILITY_MODEL_HOLDOUT_SUPPORTED':False,'UTILITY_MODEL_INSUFFICIENT':True,'UTILITY_POSITIVE_THREE_PHASE_CPU_CANDIDATE':positive>0,'NO_POSITIVE_THREE_PHASE_CANDIDATE':positive==0},'A':{'known_negative_mixed_cases':len(A),'still_selects_mixed':sum(a['still_selects_mixed'] for a in A),'development_only':True,'capacity_uncertainty_retained':True},'B':{'independent_real_system_utility_gain_contrasts':0,'status':'INSUFFICIENT_MATCHED_UTILITY_EVIDENCE','memory_and_capacity_benefits_preserved_separately':True},'C':{'independent_ranking_groups':0,'holdout_ranking_accuracy':None,'holdout_ranking_reversals':None,'retrospective_holdout_runs':len(hold),'holdout_eligible_U_runs':len(valid_hold),'holdout_absolute_U_MAE':mae,'nominal_false_feasible_runs':falsefeas,'stress_scenario_fully_finite_runs':len(cover),'finite_scenario_coverage_fraction':contained/len(cover) if cover else None,'all_holdout_stress_rejects':all(not r['stress_all_eligible'] for r in hold),'scope':'Module16 full-pool grouped holdout; not a blind prospective test. Zero independent matched ranking pairs.'},'D':perf,'E':{'main_selection_same_candidate_fraction':perf['main_selection_stability_fraction'],'negative_routing_same_fraction_across_weights':sum(a['same_fraction_as_main'] for a in Asens)/len(Asens),'not_weight_invariant':True},'F':{'cells':len(cells),'natural_structural_triples':natural,'positive_three_phase_candidates':positive,'selected_mixed_cells':mixcells,'search_is_heuristic_and_grid_limited':True},'module20b':{'positive_three_phase_efficacy_campaign_ready':False,'reason':'No positive three-phase witness; independent utility-ranking evidence insufficient and nominal holdout capacity fails. New controlled matched GPU data required before efficacy claims.','next_data_can_support_calibration_campaign':True,'automatic_GPU_launch':False},'history_integrity':None,'tests_passed':None}
 # Read existing profile and scoped calibration evidence without applying either to new scopes.
 profiles=[]
 for p in sorted((ROOT/'results/module14f_memory_ocr_x3/raw_runs').glob('*.json')):
  r=read(p);ph=r['phases']['closed_loop_capacity'];profiles.append({'run_id':r['slot']['run_id'],'model':r['slot']['model'],'count':next(iter(r['slot']['deployment'].values())),'measured_closed_loop_throughput_rps':ph.get('throughput_rps'),'all_completed':ph.get('all_requests_completed_after_drain'),'scope':'isolated measured count; not transferable co-location capacity'})
 save('parameter_evidence_audit.json',{'profile_raw_closed_loop':profiles,'independent_measured_parameters':['standalone admitted path service means: catalog source_hashes','replica g and idle M: profile sources, isolated family scaling','offered workload/schedule, handler execution and queue/E2E: raw requests','Module17 scoped mean envelopes: capacity_calibration.json and original holdout; EXACT original scope only'],'unsupported_parameters':['universal interference multiplier','absolute E2E or tail model across new combinations','statistical utility prediction intervals','transferable capacity from completed throughput at non-saturating or censored points','cross-task cardinal quality calibration'],'module17_calibration_source':ref(ROOT/'results/module17_runtime_capacity/capacity_calibration.json'),'module17_not_applied_to_optimizer':True,'nominal_predictor_has_no_fitted_parameters':True,'scenarios_are_not_calibration':True})
 checks=[]
 for p in read(OUT/'protected_before.json'):
  current=ref(p['path']);
  if current['sha256']!=p['sha256']:checks.append(p['path'])
 gate['history_integrity']={'protected_files':len(read(OUT/'protected_before.json')),'changed_files':checks,'passed':not checks};gate['tests_passed']='\nOK\n' in (OUT/'cpu_tests.log').read_text();assert not checks;assert gate['tests_passed']
 save('module20a_gate.json',gate)
 save('execution_source_manifest.json',{'at_utc':now(),'sources':[ref(p) for p in sorted((ROOT/'module20').glob('*.py'))],'python':str(ROOT/'envs/data_env/bin/python'),'environment':{'CUDA_VISIBLE_DEVICES':'','OMP_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1'},'no_GPU_runtime_imports':True,'scientific_freeze_hashes':[ref(OUT/'utility_definition.json'),ref(OUT/'utility_reference_manifest.json')]})
 report=['# Module 20A：Utility-Aware Joint Deployment and Routing Optimization — Offline Development','', '**Gate：UTILITY_MODEL_INSUFFICIENT；NO_POSITIVE_THREE_PHASE_CANDIDATE。** 两个维度独立判断。仅 CPU，未启动 GPU；原 V3、Module 19 所有负结果及历史文件均保持原样。','',f"扫描全部 {perf['cells']} 个预冻结六任务网格点：{perf['nominal_feasible_cells']} 个有名义可行候选，{perf['nominal_infeasible_or_unresolved_cells']} 个未找到；{perf['unique_candidates']} 个唯一候选、{perf['generation_attempts']} 次生成求解。没有正效用三阶段 witness；这不证明网格外或遗漏候选不存在。",'', '## 冻结效用及证据边界','', '主权重 Q/T/L/P/M = 0/0.25/0.30/0.30/0.15；敏感性为预冻结 27 个权重组合，未按结果调整。L/P 均按冻结 offered QPS 加权后逐任务参考 ms 归一化。参考是 FULL_HEAVY_19 逐任务 standalone 服务均值的中位数，用同一物理标尺衡量 mean/P95，不冒充测得 tail reference 或 SLO。', '', f"参考 ms：`{json.dumps(refs,ensure_ascii=False)}`。T 为未完成及固定 offered QPS 窗口完成损失，drain 不抹除吞吐损失；持续增长/unstable 为硬拒绝。M 为 observed safe memory/budget；历史画像未提供部署预算时 U 留空。Q_norm=null，质量仅硬准入，无假质量数据。每项 norm、加权贡献、真实 pooled-request P95、未完成/queue/worker 证据均保存在 historical_utility_analysis.csv。", '', 'U 是成本项负和，不能把 U>0 当作收益；正效用指同负载可行对照的 delta_U>0.01。三阶段按自主选择事后检查；LOW 比可行 S-only、MID 比可行 G-only、HIGH 比最佳可行纯路由有正差值才计证据，没有用不可行对照制造效用增益。', '', '## 旧算法诊断','', '|条件|CPU J GS/S ms|实测全系统 mean GS/S ms|实测 pooled P95 GS/S ms|真实 U(GS−S)|J/U 反向次数|','|---|---:|---:|---:|---:|---:|']
 for r in diagnosis:report.append(f"|{r['case']}|{r['GS_CPU_predicted_J_ms']:.4f}/{r['S_CPU_predicted_J_ms']:.4f}|{r['GS_actual_system_mean_ms']:.4f}/{r['S_actual_system_mean_ms']:.4f}|{r['GS_actual_pooled_request_P95_ms']:.4f}/{r['S_actual_pooled_request_P95_ms']:.4f}|{r['mean_delta_U_GS_minus_S']:.6f}|{r['J_U_reversals']}/3|")
 report += ['', 'Text HIGH、LID MID/HIGH：同驻留中 J 偏向 GS，而三个重复的真实 U 都偏向 S。Image HIGH 不是 J 排序反向：原操作容量 rho≤0.8 硬门槛排除了固定 S-only，尽管 GPU 三次 steady，J 本身也可偏向 S。新优化器将 .8–1 的名义可行点标成操作余量不足/待验证，不能据非饱和吞吐改写 g 或宣称新的稳定容量。', '', '误差同时涉及：(1) J 的 D/(1-rho) 队列代理与 deterministic-periodic 单快 worker 的实际排队不一致；(2) 系统目标遗漏逐任务参考归一化、tail、吞吐损失和显存取舍；(3) standalone service 在共置中不保持不变，特别是 Qwen LID、语音路径与背景任务。历史 path 的 service/s0、queue、CPU rho 与真实 worker 状态在 historical_path_diagnosis.csv 和 old_algorithm_diagnosis.csv。不能仅凭这些观察区分纯 GPU 干扰、CPU/frontend、样本差异与 runtime 状态，现有日志没有独立识别所有因果参数。', '', 'ASR HIGH 两臂 unstable 且未完成，U=null，只保留截尾诊断。Module17 的局部均值包络有原条件独立测量支持，但没有推广到新模型组合。standalone s0、实测 g/M、原始请求时序有独立画像来源；通用共置容量、service tail、统计效用界和跨任务质量标尺均没有。', '', '## 新优化器与验收','', '第一层：全部准入模型和实测 count 做线性 MILP 候选生成，目标 G 比例 free/0/0.01/0.05/0.2/0.5/1，容量 cap 0.8/0.95，3 个预冻结显存种子权重；同时保留匹配历史候选。不同部署、副本和纯/混合路由共同竞争。MILP 内的比例用于保留候选，最终选择不受阶段限制。不是完整非线性效用优化证书。', '', '第二层：固定周期到达、逐 worker FIFO、family 内 round robin，effective per-replica service=s0*n/g(n)，10 秒 warmup 后 120 秒测量。最大化 U_hat，另做相位及 1.25/2×服务压力场景。没有对 Module19 拟合校正系数；场景不是可信区间或实测保守上界。名义获选点须 rho<1；无法验证共置稳定性，全部显示 high uncertainty，stress-unstable 候选不标为认证稳定。', '', f"A：四个已知负分流条件，固定驻留候选都选择 S-only，12/12 开发配对 U 排序方向正确；27 个权重均保留该选择。Image HIGH 的 S-only 原 .8 操作门槛仍失败，所以这是条件性诊断候选，不能当成已认证基线。", '', 'B：保留并逐项报告 LOW 实测显存节省、画像副本容量收益，但没有已有独立、匹配、真实系统 U 正收益对照可以验证普遍 GS 获益排序。Module15/18 的部署 steady 和阶段行为不是反事实效用收益；不把它们充作独立胜利。所有可观察 Module19 部署对照包括正、负、同配置，均在 all_observed_deployment_contrasts.csv；完整 V3 仍未验证。', '', f"C：Module19 全部为开发集。按整个模型组合/workload 留出 Module16 六次运行；独立 matched ranking groups=0，因此排序准确率、反转数均 null。五个可评价 U 运行 MAE={mae:.6f}；名义错误判为可行：{falsefeas}。六次均无法在全部服务压力场景下保持可行；没有有限完整场景界覆盖率，不能将这种宽泛拒绝算作准确稳定性预测。该留出为回顾性，项目内已公开历史，不是盲测。", '', f"D：生成 {perf['generation_seconds']:.3f}s，预测 {perf['prediction_seconds']:.3f}s，总 wall {perf['wall_seconds']:.3f}s（单次 CPU 记录，无统计加速声称）。FULL/COMMON 原始部署 Cartesian 状态分别 {perf['naive_state_counts_by_pool']['FULL_HEAVY_19']:,}/{perf['naive_state_counts_by_pool']['COMMON_G_17']:,}，本算法共评估 {perf['unique_candidates']} 个唯一部署+路由候选。每网格 visited state 比例下降范围 {100*min(reduction):.8f}%–{100*max(reduction):.8f}%，只指省去显式枚举的状态；MILP 分支代价包含在计时，没有实测全枚举 wall speedup，也不保证全局最优。", '', f"E：27 个冻结权重下，{perf['main_selection_stability_fraction']:.2%} 的有效网格选择与主权重为同一候选；权重依赖明显，不能宣称全网格稳定。敏感性只在生成候选集上排序，未冒充完整重优化。", '', f"F：全部 210 个点和 30 个 pool/budget/target 分组均保存。自然结构三阶段组合数={natural}；严格正效用 witness={positive}；名义最优 mixed 网格点={mixcells}。没有为追求三阶段改变权重、参考、模型池、预算或 QPS。", '', '## 七项最终回答','', '1. 错预测发生在 Text HIGH、LID MID/HIGH 的 J→U 排序；Image HIGH 是保守操作容量门槛与真实运行可稳定的差异，ASR HIGH 是容量/共置不稳定漏判。', '2. 新方法直接比较全系统效用贡献，并利用周期队列模型避免 J 的过度排队收益；纯路由和多副本/部署候选始终保留。开发样本改善不是预测器已修复的证据。', '3. 尚不能证明独立效用排序正确：没有独立部署对照，且留出容量误判与效用误差明显。', '4. 预冻结六任务网格未找到理论正效用三阶段配置；不能外推为不存在。', '5. 省去的显式部署状态计数和实际 CPU 开销见上述 D；全枚举实测加速比未知，启发式覆盖有代价。', '6. 新组合 service/tail/容量、相对 U 排序、共置因果误差和真正 GS 正收益需要新的匹配 GPU 对照，按配置/workload 留出；低 QPS 背景 tail 也需更多样本。', '7. 不具备进入 Module20B 三阶段收益验证的证据；可作为另行授权校准/对照数据采集的开发输入。未创建虚假成功 witness，未自动启动 GPU。', '', f"完整性：{gate['history_integrity']['protected_files']} 个受保护文件 hash 未变；7 项 CPU 科学不变量测试通过。冻结清单、候选完整输入、失败生成尝试及执行源码 hash 均落盘。"]
 (OUT/'module20a_summary.md').write_text('\n'.join(report)+'\n')
 print('FINAL_GATE',gate['independent_dimensions'],'protected',gate['history_integrity']['protected_files'],flush=True)
